.page {
  display: grid;
  grid-template-columns: 180px 1fr 180px;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    'head head head'
    'left main right'
    'foot foot foot';
  min-height: 100vh;
}
.head { grid-area: head; display: flex; justify-content: space-between; align-items: center; }
.left { grid-area: left; }
.main { grid-area: main; }
.right { grid-area: right; }
.foot { grid-area: foot; }
